from __future__ import annotations

import ast
import tokenize
from pathlib import Path

ROOT = Path(__file__).resolve().parents[2]
PACKAGE = ROOT / "chondrotwin"
TESTS = ROOT / "provings"

FORBIDDEN = (
    "reproduction of",
    "based on the paper",
    "re-implementation",
    "following the authors",
    "as described by",
    "generated by",
    "ai-assisted",
    "placeholder",
    "todo from paper",
    "cutting-edge",
    "seamlessly",
    "delve",
    "holistic",
    "meticulously",
    "it's worth noting",
    "in conclusion",
)


def _python_files() -> list[Path]:
    return sorted([*PACKAGE.rglob("*.py"), *TESTS.rglob("*.py")])


def test_no_inline_comments() -> None:
    offenders: list[str] = []
    for path in _python_files():
        with tokenize.open(path) as handle:
            for token in tokenize.generate_tokens(handle.readline):
                if token.type == tokenize.COMMENT:
                    offenders.append(f"{path.name}:{token.start[0]}")
    assert offenders == []


def test_no_docstrings() -> None:
    holders = (ast.Module, ast.ClassDef, ast.FunctionDef, ast.AsyncFunctionDef)
    offenders: list[str] = []
    for path in _python_files():
        tree = ast.parse(path.read_text(encoding="utf-8"))
        for node in ast.walk(tree):
            if isinstance(node, holders) and ast.get_docstring(node) is not None:
                offenders.append(f"{path.name}:{getattr(node, 'name', 'module')}")
    assert offenders == []


def test_no_forbidden_phrases_or_emoji() -> None:
    guard = Path(__file__).resolve()
    scanned = [p for p in _python_files() if p.resolve() != guard]
    targets = [*scanned, ROOT / "README.md", ROOT / "Makefile"]
    offenders: list[str] = []
    for path in targets:
        if not path.exists():
            continue
        text = path.read_text(encoding="utf-8")
        lowered = text.lower()
        for phrase in FORBIDDEN:
            if phrase in lowered:
                offenders.append(f"{path.name}:{phrase}")
        for char in text:
            if ord(char) >= 0x1F000 or 0x2600 <= ord(char) <= 0x27BF:
                offenders.append(f"{path.name}:emoji")
                break
    assert offenders == []
